<?php require 'includes/layout.php';$rows=db()->query('SELECT u.username,SUM(s.score) AS points,COUNT(*) AS games FROM scores s JOIN users u ON u.id=s.user_id GROUP BY u.id,u.username ORDER BY points DESC LIMIT 20')->fetchAll();top('Leaderboard');?><div class="panel"><p>Top players by total points.</p><table><thead><tr><th>Rank</th><th>Player</th><th>Points</th><th>Games</th></tr></thead><tbody><?php foreach($rows as $i=>$r):?><tr><td><?=($i+1)?></td><td><?=e($r['username'])?></td><td><?=e($r['points'])?></td><td><?=e($r['games'])?></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><p>No scores yet. Be the first!</p><?php endif;?></div><?php bottom(); ?>